/* ==========================================================================
   Charger Calc — 充电与放电数据解析、统计指标与 IC 寄存器解码核心引擎
   ========================================================================== */

let calcRegDbRef = typeof REGISTER_DB !== 'undefined' ? REGISTER_DB : null;
if (!calcRegDbRef) {
  try {
    calcRegDbRef = require('./register-db.js').REGISTER_DB;
  } catch (_) {
    calcRegDbRef = {};
  }
}

let calcReqFieldsRef = typeof REQUIRED_CSV_FIELDS !== 'undefined' ? REQUIRED_CSV_FIELDS : null;
if (!calcReqFieldsRef) {
  try {
    calcReqFieldsRef = require('./power-standards.js').REQUIRED_CSV_FIELDS;
  } catch (_) {
    calcReqFieldsRef = ["Time","Level","Vbat","Ibat","Tbat","Status"];
  }
}

function esc(v) {
  return String(v ?? "").replace(/[&<>"']/g, m => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  }[m]));
}

function fmtNum(v, d = 2) {
  return Number.isFinite(v) ? v.toFixed(d) : "—";
}

function fmtMin(v) {
  if (!Number.isFinite(v)) return "—";
  const s = Math.round(v * 60);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return h ? `${h}小时${String(m).padStart(2, "0")}分${String(sec).padStart(2, "0")}秒` : `${m}分${String(sec).padStart(2, "0")}秒`;
}

function fmtClock(ms) {
  if (!Number.isFinite(ms)) return "—";
  const d = new Date(ms);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}:${String(d.getSeconds()).padStart(2, "0")}`;
}

function parseTime(s) {
  s = String(s ?? "").trim();
  let m = s.match(/^(\d{4})[_-](\d{2})[_-](\d{2})\s+(\d{2}):(\d{2}):(\d{2})(?:\.(\d+))?$/);
  if (m) {
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6], m[7] ? Number(("0." + m[7])) * 1000 : 0).getTime();
  }
  const t = Date.parse(s.replace(/_/g, "-"));
  return Number.isFinite(t) ? t : NaN;
}

function csvSplitLine(line) {
  const out = [];
  let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (q && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else {
        q = !q;
      }
    } else if (c === ',' && !q) {
      out.push(cur);
      cur = "";
    } else {
      cur += c;
    }
  }
  out.push(cur);
  return out;
}

function parseCSV(text) {
  text = String(text).replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trim();
  const lines = text.split("\n").filter(x => x.trim() !== "");
  if (lines.length < 2) throw new Error("CSV 没有有效数据行");
  const headers = csvSplitLine(lines[0]).map(x => x.trim());
  const missing = calcReqFieldsRef.filter(k => !headers.includes(k));
  if (missing.length) throw new Error("缺少必要字段：" + missing.join(", "));
  const idx = Object.fromEntries(headers.map((h, i) => [h, i]));
  const rows = [];
  let badTime = 0, badNumeric = 0, zeroVoltage = 0;
  for (let i = 1; i < lines.length; i++) {
    const a = csvSplitLine(lines[i]);
    if (a.length < headers.length) continue;
    const t = parseTime(a[idx.Time]);
    if (!Number.isFinite(t)) { badTime++; continue; }
    const r = {
      Time: a[idx.Time],
      time: t,
      Level: Number(a[idx.Level]),
      Vbat: Number(a[idx.Vbat]),
      Ibat: Number(a[idx.Ibat]),
      Tbat: Number(a[idx.Tbat]),
      Status: String(a[idx.Status] ?? "").trim()
    };
    if (![r.Level, r.Vbat, r.Ibat, r.Tbat].every(Number.isFinite)) { badNumeric++; continue; }
    if (r.Vbat === 0) { zeroVoltage++; continue; }
    rows.push(r);
  }
  if (rows.length < 2) throw new Error(zeroVoltage ? `有效数据不足（已忽略 ${zeroVoltage} 行电池电压为 0 的异常数据）` : "有效数据不足");
  rows.sort((a, b) => a.time - b.time);
  let nonIncreasing = 0;
  for (let i = 1; i < rows.length; i++) {
    if (rows[i].time <= rows[i - 1].time) nonIncreasing++;
  }
  return { headers, rows, quality: { badTime, badNumeric, zeroVoltage, nonIncreasing } };
}

function validateSummary(data) {
  const r = data.rows;
  const charging = r.filter(x => /^charging$/i.test(x.Status)).length;
  const full = r.filter(x => /^full$/i.test(x.Status)).length;
  return `
    <div class="tw-chg-notice tw-chg-notice-good">✓ 文件检查通过，有效样本 ${r.length} 行，可以生成分析报告。</div>
    <div class="tw-chg-validation-grid">
      <div class="tw-chg-vcard"><b>✓ 数据行数</b>${r.length} 行</div>
      <div class="tw-chg-vcard"><b>✓ 必要字段</b>${calcReqFieldsRef.join(", ")}</div>
      <div class="tw-chg-vcard"><b>✓ 时间顺序</b>${data.quality.nonIncreasing ? "存在 " + data.quality.nonIncreasing + " 个非递增点" : "完全单调递增"}</div>
      <div class="tw-chg-vcard"><b>✓ Charging 行数</b>${charging} 行</div>
      <div class="tw-chg-vcard"><b>✓ Full 截止点</b>${full} 行${full ? "（首次 Full 为截止点）" : "（未发现 Full 状态）"}</div>
      <div class="tw-chg-vcard"><b>✓ 脏数据过滤</b>时间异常 ${data.quality.badTime} / 数值异常 ${data.quality.badNumeric} / 0V剔除 ${data.quality.zeroVoltage || 0}</div>
    </div>
  `;
}

function analyze(data) {
  const rows = data.rows;
  let startIdx = rows.findIndex(x => /^charging$/i.test(x.Status));
  if (startIdx < 0) startIdx = 0;
  const start = rows[startIdx];
  const startTime = start.time;
  const firstAt = p => rows.find((x, i) => i >= startIdx && x.Level >= p);
  const p50 = firstAt(50), p80 = firstAt(80), p100 = firstAt(100);
  const fullIdx = rows.findIndex((x, i) => i >= startIdx && /^full$/i.test(x.Status));
  const full = fullIdx >= 0 ? rows[fullIdx] : null;
  let prevCharging = null;
  if (fullIdx >= 0) {
    for (let i = fullIdx - 1; i >= startIdx; i--) {
      if (/^charging$/i.test(rows[i].Status)) {
        prevCharging = rows[i];
        break;
      }
    }
  }
  const endIdx = fullIdx >= 0 ? fullIdx : rows.length - 1;
  const win = rows.slice(startIdx, endIdx + 1);
  const elapsed = x => x ? (x.time - startTime) / 60000 : NaN;
  let ah = 0, wh = 0;
  for (let i = startIdx + 1; i <= endIdx; i++) {
    const a = rows[i - 1], b = rows[i];
    const dt = (b.time - a.time) / 3600000;
    if (!(dt > 0 && dt < 1)) continue;
    const ia = Math.max(0, a.Ibat) / 1000, ib = Math.max(0, b.Ibat) / 1000;
    const va = a.Vbat / 1000, vb = b.Vbat / 1000;
    ah += (ia + ib) / 2 * dt;
    wh += ((ia * va) + (ib * vb)) / 2 * dt;
  }
  const avg = (arr, key) => arr.length ? arr.reduce((s, x) => s + x[key], 0) / arr.length : NaN;
  const max = (arr, key) => arr.length ? Math.max(...arr.map(x => x[key])) : NaN;
  const stages = [];
  for (let lo = 0; lo < 100; lo += 10) {
    const hi = lo + 10;
    const a = rows.find((x, i) => i >= startIdx && x.Level >= Math.max(lo, start.Level));
    const b = rows.find((x, i) => i >= startIdx && x.Level >= hi);
    const seg = win.filter(x => x.Level >= lo && x.Level < hi);
    stages.push({
      range: `${lo}-${hi}%`,
      duration: a && b ? (b.time - a.time) / 60000 : NaN,
      avgI: avg(seg, "Ibat"),
      avgV: avg(seg, "Vbat"),
      avgT: avg(seg, "Tbat"),
      maxT: max(seg, "Tbat")
    });
  }
  return {
    start, p50, p80, p100, full, prevCharging,
    t50: elapsed(p50), t80: elapsed(p80), t100: elapsed(p100), tFull: elapsed(full),
    ah, wh, avgI: avg(win, "Ibat"), peakI: max(win, "Ibat"), avgV: avg(win, "Vbat"), peakV: max(win, "Vbat"), maxT: max(win, "Tbat"),
    cutoffI: prevCharging ? prevCharging.Ibat : NaN, fullV: prevCharging ? prevCharging.Vbat : NaN, stages, win
  };
}

// ================= 放电分析核心计算 =================
function dischargeIntegrateRows(rows) {
  if (!rows || rows.length < 2) return { mah: NaN, wh: NaN, duration: NaN, avgCurrent: NaN };
  let mah = 0, wh = 0;
  for (let i = 1; i < rows.length; i++) {
    const dt = (rows[i].time - rows[i - 1].time) / 3600000;
    if (!(dt > 0)) continue;
    const cur = (Math.abs(Number(rows[i].Ibat)) + Math.abs(Number(rows[i - 1].Ibat))) / 2;
    const vol = (Number(rows[i].Vbat) + Number(rows[i - 1].Vbat)) / 2 / 1000;
    if (!Number.isFinite(cur) || !Number.isFinite(vol)) continue;
    mah += cur * dt;
    wh += cur * dt * vol / 1000;
  }
  const duration = (rows[rows.length - 1].time - rows[0].time) / 60000;
  const avgCurrent = duration > 0 ? mah / (duration / 60) : NaN;
  return { mah, wh, duration, avgCurrent };
}

function dischargeMedian(values) {
  const a = values.filter(Number.isFinite).slice().sort((x, y) => x - y);
  if (!a.length) return NaN;
  const m = Math.floor(a.length / 2);
  return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
}

function dischargeWindowStats(rows) {
  if (!rows || !rows.length) return { duration: NaN, mah: NaN, wh: NaN, avgCurrent: NaN, startV: NaN, endV: NaN, deltaV: NaN, minV: NaN, avgV: NaN, startLevel: NaN, endLevel: NaN, socSpan: NaN };
  const integ = dischargeIntegrateRows(rows);
  const start = rows[0], end = rows[rows.length - 1];
  const volts = rows.map(x => Number(x.Vbat)).filter(Number.isFinite);
  const avgV = Number.isFinite(integ.mah) && integ.mah > 0 && Number.isFinite(integ.wh)
    ? integ.wh / (integ.mah / 1000) * 1000
    : (volts.length ? volts.reduce((a, b) => a + b, 0) / volts.length : NaN);
  return {
    ...integ,
    startV: Number(start.Vbat),
    endV: Number(end.Vbat),
    deltaV: Number(end.Vbat) - Number(start.Vbat),
    minV: volts.length ? Math.min(...volts) : NaN,
    avgV,
    startLevel: Number(start.Level),
    endLevel: Number(end.Level),
    socSpan: Math.abs(Number(start.Level) - Number(end.Level))
  };
}

function dischargeAnalyze(data) {
  const r = data.rows.filter(x => /discharge/i.test(x.Status) || true);
  const start = r[0], end = r[r.length - 1];
  const whole = dischargeIntegrateRows(r);
  const duration = (end.time - start.time) / 60000;
  const mah = Number.isFinite(whole.mah) ? whole.mah : 0;
  const wh = Number.isFinite(whole.wh) ? whole.wh : 0;
  const avgI = duration > 0 ? mah / (duration / 60) : r.reduce((a, x) => a + Math.abs(x.Ibat), 0) / r.length;
  const peakI = Math.max(...r.map(x => Math.abs(x.Ibat)));
  const ranges = [];
  for (let hi = 100; hi > 0; hi -= 10) {
    const lo = hi - 10;
    let ai = r.findIndex(x => Number(x.Level) <= hi && Number(x.Level) > lo);
    let bi = -1, rangeLabel = hi + "-" + lo + "%";
    if (ai >= 0) bi = r.findIndex((x, i) => i >= ai && Number(x.Level) <= lo);
    if (hi === 10 && ai >= 0 && bi < 0 && Number.isFinite(Number(end.Level)) && Number(end.Level) < 10) {
      bi = r.length - 1;
      rangeLabel = `10-${Number(end.Level).toFixed(Number.isInteger(Number(end.Level)) ? 0 : 1)}%（关机）`;
    }
    const a = ai >= 0 ? r[ai] : null, b = bi >= 0 ? r[bi] : null;
    const seg = (a && b && bi >= ai) ? r.slice(ai, bi + 1) : [];
    const stats = dischargeWindowStats(seg);
    const startV = a ? Number(a.Vbat) : NaN, endV = b ? Number(b.Vbat) : NaN;
    const socSpan = a && b ? Math.abs(Number(a.Level) - Number(b.Level)) : NaN;
    const rangeDuration = a && b ? Math.max(0, (b.time - a.time) / 60000) : NaN;
    const capacityMah = stats.mah, energyWh = stats.wh;
    const avgCurrent = Number.isFinite(stats.avgCurrent) ? stats.avgCurrent : NaN;
    const deltaV = Number.isFinite(startV) && Number.isFinite(endV) ? endV - startV : NaN;
    ranges.push({
      hi, lo, range: rangeLabel, duration: rangeDuration, socSpan, avgCurrent, startV, endV, deltaV, capacityMah, energyWh,
      minPerPct: Number.isFinite(rangeDuration) && socSpan > 0 ? rangeDuration / socSpan : NaN,
      mahPerPct: Number.isFinite(capacityMah) && socSpan > 0 ? capacityMah / socSpan : NaN,
      mvPerPct: Number.isFinite(deltaV) && socSpan > 0 ? Math.abs(deltaV) / socSpan : NaN
    });
  }
  const mid = ranges.filter(x => x.hi <= 90 && x.lo >= 20 && Number.isFinite(x.mahPerPct));
  const baselineMahPerPct = dischargeMedian(mid.map(x => x.mahPerPct));
  const baselineMvPerPct = dischargeMedian(mid.map(x => x.mvPerPct));
  ranges.forEach(x => {
    x.capacityDeviation = Number.isFinite(baselineMahPerPct) && baselineMahPerPct > 0 && Number.isFinite(x.mahPerPct)
      ? (x.mahPerPct - baselineMahPerPct) / baselineMahPerPct * 100 : NaN;
    const tags = []; let cls = "good";
    const lowRange = x.hi <= 20;
    if (lowRange && Number.isFinite(baselineMvPerPct) && baselineMvPerPct > 0 && Number.isFinite(x.mvPerPct) && x.mvPerPct > baselineMvPerPct * 1.6) {
      tags.push("末端掉压快"); cls = "bad";
    }
    if (Number.isFinite(x.capacityDeviation)) {
      if (x.capacityDeviation >= 20) { tags.push("SOC偏慢"); cls = "bad"; }
      else if (x.capacityDeviation >= 10) { tags.push("SOC偏慢"); if (cls === "good") cls = "warn"; }
      else if (x.capacityDeviation <= -20) { tags.push("SOC偏快"); cls = "bad"; }
      else if (x.capacityDeviation <= -10) { tags.push("SOC偏快"); if (cls === "good") cls = "warn"; }
    }
    if (Number.isFinite(x.avgCurrent) && Number.isFinite(avgI) && avgI > 0 && x.avgCurrent > avgI * 1.25) {
      tags.push("负载偏高"); if (cls === "good") cls = "warn";
    }
    x.status = tags.length ? tags.join(" / ") : "正常";
    x.statusClass = cls;
  });
  const low20StartIndex = r.findIndex(x => Number(x.Level) <= 20);
  const low20Rows = low20StartIndex >= 0 ? r.slice(low20StartIndex) : [];
  const low20 = dischargeWindowStats(low20Rows);
  const last5Target = Math.min(Number(start.Level), Number(end.Level) + 5);
  const last5StartIndex = r.findIndex(x => Number(x.Level) <= last5Target);
  const last5Rows = last5StartIndex >= 0 ? r.slice(last5StartIndex) : [];
  const last5Soc = dischargeWindowStats(last5Rows);
  const final5MinRows = r.filter(x => x.time >= end.time - 5 * 60000);
  const final5Min = dischargeWindowStats(final5MinRows);
  const minMax = k => [Math.min(...r.map(x => x[k])), Math.max(...r.map(x => x[k]))];
  return {
    r, start, end, duration, ranges, volt: minMax("Vbat"), temp: minMax("Tbat"), curr: minMax("Ibat"), mah, wh, avgI, peakI,
    baselineMahPerPct, baselineMvPerPct, lowBattery: { low20, last5Soc, final5Min, shutdownSoc: Number(end.Level) }
  };
}

function movingAverage(rows, key, windowSize = 15, useAbs = false) {
  const n = rows.length, w = Math.max(3, Math.min(windowSize, n || 3)), half = Math.floor(w / 2), out = [];
  for (let i = 0; i < n; i++) {
    let sum = 0, count = 0;
    for (let j = Math.max(0, i - half); j <= Math.min(n - 1, i + half); j++) {
      const raw = Number(rows[j][key]);
      if (!Number.isFinite(raw)) continue;
      sum += useAbs ? Math.abs(raw) : raw;
      count++;
    }
    out.push(count ? sum / count : NaN);
  }
  return out;
}

function formatDischargeTime(t) {
  const d = new Date(t);
  if (Number.isNaN(d.getTime())) return "-";
  const z = n => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())} ${z(d.getHours())}:${z(d.getMinutes())}:${z(d.getSeconds())}`;
}

// ================= IC 寄存器解析核心计算 =================
function detectChip(text) {
  const up = String(text).toUpperCase();
  const db = calcRegDbRef || {};
  for (const c of Object.keys(db)) {
    if (up.includes(c.toUpperCase())) return c;
  }
  const m = up.match(/\b(?:SC|UPM)\d+[A-Z0-9]*\b/);
  return m ? m[0] : null;
}

function parseDump(text) {
  const values = new Map(), occ = new Map();
  const re = /reg(?:ister)?\s*\[\s*(0x[0-9a-f]+)\s*\]\s*=\s*(0x[0-9a-f]+)/ig;
  let m;
  while ((m = re.exec(text))) {
    const a = parseInt(m[1], 16), v = parseInt(m[2], 16) & 0xFF;
    values.set(a, v);
    occ.set(a, (occ.get(a) || 0) + 1);
  }
  if (!values.size) {
    const re2 = /(0x[0-9a-f]{1,4})\s*(?:=|:)\s*(0x[0-9a-f]{1,2})/ig;
    while ((m = re2.exec(text))) {
      const a = parseInt(m[1], 16), v = parseInt(m[2], 16) & 0xFF;
      values.set(a, v);
      occ.set(a, (occ.get(a) || 0) + 1);
    }
  }
  return { values, occ, detected: detectChip(text) };
}

function fieldRaw(regVal, f) {
  const width = f.hi - f.lo + 1;
  return (regVal >>> f.lo) & ((1 << width) - 1);
}

function parseEnum(desc, raw, width) {
  const lines = String(desc || "").split(/\n/);
  for (let line of lines) {
    line = line.trim().replace(/[–—]/g, "-");
    let m = line.match(/^((?:0x)?[0-9A-Fa-f]+h?|[01]+)\s*(?::|=|\s-\s)\s*(.+)$/);
    if (!m) continue;
    const tok = m[1];
    if (/[~～]/.test(tok)) continue;
    let val;
    if (/^0x/i.test(tok)) val = parseInt(tok, 16);
    else if (/h$/i.test(tok)) val = parseInt(tok.slice(0, -1), 16);
    else if (/^[01]+$/.test(tok)) val = parseInt(tok, 2);
    else continue;
    if (val === raw) return m[2].trim();
  }
  return "";
}

function fmtSmart(v) {
  if (!Number.isFinite(v)) return "—";
  return Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : v.toFixed(3).replace(/0+$/, "").replace(/\.$/, "");
}

function decodedField(regVal, f) {
  const raw = fieldRaw(regVal, f);
  const width = f.hi - f.lo + 1;
  let physical = null, meaning = "";
  if (f.split_weights) {
    let v = Number(f.split_weights.offset || 0);
    const weights = f.split_weights.weights || {};
    for (let bit = f.lo; bit <= f.hi; bit++) {
      if ((regVal >> bit) & 1) v += Number(weights[String(bit)] || 0);
    }
    physical = { value: v, unit: f.split_weights.unit || "" };
    meaning = `${fmtSmart(v)} ${physical.unit}`.trim();
  } else if (f.physical) {
    const v = raw * Number(f.physical.gain || 0) + Number(f.physical.offset || 0);
    physical = { value: v, unit: f.physical.unit || "" };
    meaning = `${fmtSmart(v)} ${physical.unit}`.trim();
  } else {
    meaning = parseEnum(f.desc, raw, width);
  }
  if (!meaning) meaning = `${raw} (0b${raw.toString(2).padStart(width, "0")})`;
  return { raw, width, meaning, physical };
}

function getRegDef(chip, addr) {
  const db = calcRegDbRef || {};
  return chip && db[chip] ? db[chip][addr.toString(16).padStart(2, "0").toUpperCase()] || null : null;
}

function regHex(v) {
  return Number.isFinite(v) ? "0x" + v.toString(16).padStart(2, "0").toUpperCase() : "缺失";
}

function bitRange(f) {
  return f.hi === f.lo ? String(f.hi) : `${f.hi}:${f.lo}`;
}

function binaryDiff(a, b) {
  let A = "", B = "";
  for (let bit = 7; bit >= 0; bit--) {
    const ca = (a >> bit) & 1, cb = (b >> bit) & 1, chg = ca !== cb;
    A += chg ? `<span class="tw-chg-bit-changed">${ca}</span>` : ca;
    B += chg ? `<span class="tw-chg-bit-changed">${cb}</span>` : cb;
    if (bit > 0) { A += " "; B += " "; }
  }
  return { A, B };
}

function fieldDelta(da, db) {
  if (da?.physical && db?.physical && da.physical.unit === db.physical.unit) {
    const d = db.physical.value - da.physical.value;
    return `${d > 0 ? "+" : ""}${fmtSmart(d)} ${da.physical.unit}`;
  }
  return "—";
}

if (typeof module !== 'undefined' && module.exports) {
  
}

/* ==========================================================================
   Charger Charts — 原生 Canvas 多轴曲线、示波器与交互渲染引擎
   ========================================================================== */

let movingAverageRef = typeof movingAverage === 'function' ? movingAverage : null;
let formatDischargeTimeRef = typeof formatDischargeTime === 'function' ? formatDischargeTime : null;
if (!movingAverageRef || !formatDischargeTimeRef) {
  try {
    
    if (!movingAverageRef) movingAverageRef = calc.movingAverage;
    if (!formatDischargeTimeRef) formatDischargeTimeRef = calc.formatDischargeTime;
  } catch (_) {
    if (!movingAverageRef) movingAverageRef = (r, k) => r.map(x => x[k]);
    if (!formatDischargeTimeRef) formatDischargeTimeRef = t => String(t);
  }
}

function ensureChartTip(canvas) {
  const box = canvas.parentElement;
  let tip = box.querySelector(".tw-chg-chart-tip");
  if (!tip) {
    tip = document.createElement("div");
    tip.className = "tw-chg-chart-tip";
    box.appendChild(tip);
  }
  return tip;
}

function canvasChart(canvas, series, opts = {}) {
  if (!canvas) return;
  const box = canvas.parentElement;
  const tip = ensureChartTip(canvas);
  const ctx = canvas.getContext("2d");
  const dpr = window.devicePixelRatio || 1;

  function draw() {
    const rect = box.getBoundingClientRect();
    canvas.width = Math.max(300, rect.width) * dpr;
    canvas.height = Math.max(180, rect.height) * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const W = rect.width, H = rect.height;
    const p = { l: 50, r: 50, t: 22, b: 34 };
    const w = W - p.l - p.r, h = H - p.t - p.b;

    const allX = series.flatMap(s => s.data.map(d => d.x)).filter(Number.isFinite);
    if (!allX.length) return;
    const xmin = Math.min(...allX);
    const xmax = Math.max(...allX) || 1;
    const axes = [...new Set(series.map(s => s.axis || "left"))];
    const yRange = {};

    for (const ax of axes) {
      const vals = series.filter(s => (s.axis || "left") === ax).flatMap(s => s.data.map(d => d.y)).filter(Number.isFinite);
      let mn = Math.min(...vals), mx = Math.max(...vals);
      if (mn === mx) { mn -= 1; mx += 1; }
      const pad = (mx - mn) * 0.08;
      yRange[ax] = [mn - pad, mx + pad];
    }

    ctx.clearRect(0, 0, W, H);
    ctx.strokeStyle = "rgba(120, 130, 150, 0.2)";
    ctx.lineWidth = 1;
    ctx.fillStyle = "#7a8295";
    ctx.font = "11px 'Segoe UI', system-ui, sans-serif";

    for (let i = 0; i <= 5; i++) {
      const y = p.t + h * i / 5;
      ctx.beginPath();
      ctx.moveTo(p.l, y);
      ctx.lineTo(W - p.r, y);
      ctx.stroke();
      const [mn, mx] = yRange.left || yRange[axes[0]];
      ctx.fillText((mx - (mx - mn) * i / 5).toFixed(opts.leftDigits ?? 0), 4, y + 4);
    }

    if (yRange.right) {
      const [mn, mx] = yRange.right;
      for (let i = 0; i <= 5; i++) {
        const y = p.t + h * i / 5;
        const txt = (mx - (mx - mn) * i / 5).toFixed(opts.rightDigits ?? 0);
        ctx.fillText(txt, W - p.r + 6, y + 4);
      }
    }

    ctx.fillText("时间 (min)", Math.max(p.l, W / 2 - 24), H - 7);
    const colors = ["#5968e8", "#e18b2f", "#18a06e", "#c04693"];

    series.forEach((s, si) => {
      const [mn, mx] = yRange[s.axis || "left"];
      ctx.strokeStyle = colors[si % colors.length];
      ctx.lineWidth = 1.8;
      ctx.beginPath();
      s.data.forEach((d, i) => {
        const x = p.l + (d.x - xmin) / (xmax - xmin || 1) * w;
        const y = p.t + (mx - d.y) / (mx - mn) * h;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    });

    series.forEach((s, si) => {
      ctx.fillStyle = colors[si % colors.length];
      ctx.fillRect(p.l + si * 145, p.t - 15, 10, 3);
      ctx.fillStyle = "#6b7280";
      ctx.fillText(`${s.name} (${s.unit || ""})`, p.l + 14 + si * 145, p.t - 9);
    });

    canvas._chart = { p, w, h, xmin, xmax, yRange, series, colors };
  }

  function pointer(ev) {
    const c = canvas._chart;
    if (!c) return;
    const r = canvas.getBoundingClientRect();
    const mx = (ev.touches ? ev.touches[0].clientX : ev.clientX) - r.left;
    const xval = c.xmin + Math.max(0, Math.min(c.w, mx - c.p.l)) / c.w * (c.xmax - c.xmin);
    let nearest = null, nd = Infinity;
    const base = c.series[0].data;
    for (const d of base) {
      const dd = Math.abs(d.x - xval);
      if (dd < nd) { nd = dd; nearest = d; }
    }
    if (!nearest) return;
    const lines = [`时间：${nearest.x.toFixed(2)} min`];
    c.series.forEach(s => {
      let n = s.data.reduce((best, d) => Math.abs(d.x - nearest.x) < Math.abs(best.x - nearest.x) ? d : best, s.data[0]);
      lines.push(`${s.name}：${Number(n.y).toFixed(s.digits ?? 1)} ${s.unit || ""}`);
    });
    tip.innerHTML = lines.join("<br>");
    tip.style.display = "block";
    const left = Math.min(r.width - 150, Math.max(5, mx + 10));
    tip.style.left = left + "px";
    tip.style.top = "35px";
  }

  canvas.addEventListener("mousemove", pointer);
  canvas.addEventListener("touchmove", pointer, { passive: true });
  canvas.addEventListener("mouseleave", () => { tip.style.display = "none"; });

  draw();
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(draw).observe(box);
  }
}

function drawSingleCharts(container, m) {
  if (!container || !m || !m.win) return;
  const t0 = m.start.time;
  const pts = m.win.map(x => ({ x: (x.time - t0) / 60000, I: x.Ibat, V: x.Vbat, T: x.Tbat }));

  const c1 = container.querySelector("#chargeChart");
  if (c1) {
    canvasChart(c1, [
      { name: "电池电流", unit: "mA", axis: "left", digits: 0, data: pts.map(p => ({ x: p.x, y: p.I })) },
      { name: "电池电压", unit: "mV", axis: "right", digits: 0, data: pts.map(p => ({ x: p.x, y: p.V })) }
    ], { leftDigits: 0, rightDigits: 0 });
  }

  const c2 = container.querySelector("#tempChart");
  if (c2) {
    canvasChart(c2, [
      { name: "电池温度", unit: "°C", axis: "left", digits: 1, data: pts.map(p => ({ x: p.x, y: p.T })) },
      { name: "电池电流", unit: "mA", axis: "right", digits: 0, data: pts.map(p => ({ x: p.x, y: p.I })) }
    ], { leftDigits: 1, rightDigits: 0 });
  }
}

function drawCompareCharts(container, a, b) {
  if (!container || !a || !b) return;
  const toSeries = (m, key) => m.win.map(x => ({ x: (x.time - m.start.time) / 60000, y: x[key] }));

  const c1 = container.querySelector("#cmpCurrent");
  if (c1) {
    canvasChart(c1, [
      { name: "数据 A", unit: "mA", data: toSeries(a, "Ibat"), digits: 0 },
      { name: "数据 B", unit: "mA", data: toSeries(b, "Ibat"), digits: 0 }
    ], { leftDigits: 0 });
  }

  const c2 = container.querySelector("#cmpTemp");
  if (c2) {
    canvasChart(c2, [
      { name: "数据 A", unit: "°C", data: toSeries(a, "Tbat"), digits: 1 },
      { name: "数据 B", unit: "°C", data: toSeries(b, "Tbat"), digits: 1 }
    ], { leftDigits: 1 });
  }
}

// ================= 放电多轴与对比 Canvas 引擎 =================
function drawMultiChart(canvas, rows, series) {
  if (!canvas || !rows || !rows.length) return;
  const c = canvas, ctx = c.getContext("2d");
  const tip = ensureChartTip(canvas);
  let pinned = false, lastRatio = -1;

  function draw(ratio = -1) {
    const W = c.clientWidth, H = c.clientHeight;
    const dpr = window.devicePixelRatio || 2;
    const pad = { l: 45, r: series.length > 1 ? 45 : 18, t: 26, b: 24 };
    c.width = Math.max(1, W * dpr);
    c.height = Math.max(1, H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);

    const pw = Math.max(1, W - pad.l - pad.r);
    const ph = Math.max(1, H - pad.t - pad.b);
    const colors = ["#5a67e8", "#17a36f", "#e08d24", "#d9424a"];

    series.forEach((s, idx) => {
      const vals = rows.map(x => Number(x[s.key])).filter(Number.isFinite);
      const mn = Math.min(...vals), mx = Math.max(...vals);
      const isRight = idx === 1;

      ctx.beginPath();
      rows.forEach((x, i) => {
        const v = Number(x[s.key]);
        if (!Number.isFinite(v)) return;
        const px = pad.l + (rows.length <= 1 ? 0 : i / (rows.length - 1)) * pw;
        const py = pad.t + (mx - v) / (mx - mn || 1) * ph;
        i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
      });
      ctx.strokeStyle = colors[idx % colors.length];
      ctx.lineWidth = 1.6;
      ctx.stroke();

      if (s.key === "Ibat") {
        const mv = movingAverageRef(rows, "Ibat", 15, true);
        ctx.beginPath();
        mv.forEach((v, i) => {
          const px = pad.l + (rows.length <= 1 ? 0 : i / (rows.length - 1)) * pw;
          const py = pad.t + (mx - v) / (mx - mn || 1) * ph;
          i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
        });
        ctx.strokeStyle = colors[idx % colors.length];
        ctx.lineWidth = 2.2;
        ctx.setLineDash([6, 3]);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      ctx.font = "11px 'Segoe UI', system-ui, sans-serif";
      ctx.fillStyle = colors[idx % colors.length];
      ctx.fillText(`${s.key} (${mn.toFixed(1)}~${mx.toFixed(1)}${s.unit})`, isRight ? W - pad.r - 80 : pad.l, 14);
    });

    if (ratio >= 0) {
      const x = pad.l + ratio * pw;
      ctx.strokeStyle = "#4b5563";
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(x, pad.t);
      ctx.lineTo(x, H - pad.b);
      ctx.stroke();
      ctx.setLineDash([]);
    }
    c._geom = { pad, pw, W, H };
  }

  function showAt(ev, lock = false) {
    const r = c.getBoundingClientRect(), g = c._geom;
    if (!g) return;
    const mx = (ev.touches ? ev.touches[0].clientX : ev.clientX) - r.left;
    const ratio = Math.max(0, Math.min(1, (mx - g.pad.l) / g.pw));
    lastRatio = ratio;
    if (lock) pinned = true;
    draw(ratio);
    const idx = Math.max(0, Math.min(rows.length - 1, Math.round(ratio * (rows.length - 1))));
    const item = rows[idx];
    let tipHtml = `<b>时间:</b> ${formatDischargeTimeRef(item.time)}<br>`;
    series.forEach(s => {
      tipHtml += `<b>${s.key}:</b> ${Number(item[s.key]).toFixed(1)} ${s.unit}<br>`;
    });
    tip.innerHTML = tipHtml;
    tip.style.display = "block";
    tip.style.left = Math.min(Math.max(5, g.pad.l + ratio * g.pw + 10), Math.max(5, r.width - 200)) + "px";
    tip.style.top = "30px";
  }

  c.onmousemove = e => { if (!pinned) showAt(e, false); };
  c.onclick = e => showAt(e, true);
  c.onmouseleave = () => { if (!pinned) { tip.style.display = "none"; draw(-1); } };
  c.ondblclick = () => { pinned = false; lastRatio = -1; tip.style.display = "none"; draw(-1); };

  draw();
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(() => draw(lastRatio)).observe(c.parentElement);
  }
}

function drawDischargeCompareChart(canvas, aRows, bRows, key, unit, useAbs = false) {
  if (!canvas || !aRows || !bRows) return;
  const c = canvas, ctx = c.getContext("2d");
  const tip = ensureChartTip(canvas);
  let pinned = false, lastRatio = -1;
  const val = x => useAbs ? Math.abs(Number(x[key])) : Number(x[key]);

  function draw(ratio = -1) {
    const W = c.clientWidth, H = c.clientHeight;
    const dpr = window.devicePixelRatio || 2;
    const pad = { l: 42, r: 18, t: 28, b: 24 };
    c.width = Math.max(1, W * dpr);
    c.height = Math.max(1, H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);

    const pw = Math.max(1, W - pad.l - pad.r);
    const ph = Math.max(1, H - pad.t - pad.b);
    const all = aRows.concat(bRows).map(val).filter(Number.isFinite);
    const mn = Math.min(...all), mx = Math.max(...all);

    const line = (rows, color) => {
      ctx.beginPath();
      rows.forEach((x, i) => {
        const v = val(x);
        if (!Number.isFinite(v)) return;
        const px = pad.l + (rows.length <= 1 ? 0 : i / (rows.length - 1)) * pw;
        const py = pad.t + (mx - v) / (mx - mn || 1) * ph;
        i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
      });
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.4;
      ctx.globalAlpha = 0.45;
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    const filtered = (rows, color) => {
      const vs = movingAverageRef(rows, key, 15, useAbs);
      ctx.beginPath();
      vs.forEach((v, i) => {
        const px = pad.l + (rows.length <= 1 ? 0 : i / (rows.length - 1)) * pw;
        const py = pad.t + (mx - v) / (mx - mn || 1) * ph;
        i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
      });
      ctx.strokeStyle = color;
      ctx.lineWidth = 2.4;
      ctx.setLineDash([7, 4]);
      ctx.stroke();
      ctx.setLineDash([]);
    };

    line(aRows, "#5a67e8");
    line(bRows, "#d88412");
    if (key === "Ibat") {
      filtered(aRows, "#5a67e8");
      filtered(bRows, "#d88412");
    }

    ctx.font = "11px 'Segoe UI', system-ui, sans-serif";
    ctx.fillStyle = "#5a67e8"; ctx.fillText("A", 6, 14);
    ctx.fillStyle = "#d88412"; ctx.fillText("B", 24, 14);
    ctx.fillStyle = "#555"; ctx.fillText(`${mn.toFixed(1)} ~ ${mx.toFixed(1)} ${unit}${key === "Ibat" ? " (虚线=15点滤波)" : ""}`, 44, 14);

    if (ratio >= 0) {
      const x = pad.l + ratio * pw;
      ctx.strokeStyle = "#4b5563";
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(x, pad.t);
      ctx.lineTo(x, H - pad.b);
      ctx.stroke();
      ctx.setLineDash([]);
    }
    c._dccGeom = { pad, pw, W, H };
  }

  function nearest(rows, ratio) {
    return rows[Math.max(0, Math.min(rows.length - 1, Math.round(ratio * (rows.length - 1))))];
  }

  function showAt(ev, lock = false) {
    const r = c.getBoundingClientRect(), g = c._dccGeom;
    if (!g) return;
    const mx = (ev.touches ? ev.touches[0].clientX : ev.clientX) - r.left;
    const ratio = Math.max(0, Math.min(1, (mx - g.pad.l) / g.pw));
    lastRatio = ratio;
    if (lock) pinned = true;
    draw(ratio);
    const A = nearest(aRows, ratio), B = nearest(bRows, ratio);
    const one = (n, x) => `<b>${n}</b> ${formatDischargeTimeRef(x.time)}<br>SOC ${Number(x.Level).toFixed(0)}% · V ${Number(x.Vbat).toFixed(0)}mV · I ${Number(x.Ibat).toFixed(0)}mA · T ${Number(x.Tbat).toFixed(1)}℃`;
    tip.innerHTML = one("A: ", A) + "<br>" + one("B: ", B);
    tip.style.display = "block";
    tip.style.left = Math.min(Math.max(5, g.pad.l + ratio * g.pw + 10), Math.max(5, r.width - 250)) + "px";
    tip.style.top = "34px";
  }

  c.onmousemove = e => { if (!pinned) showAt(e, false); };
  c.onclick = e => showAt(e, true);
  c.onmouseleave = () => { if (!pinned) { tip.style.display = "none"; draw(-1); } };
  c.ondblclick = () => { pinned = false; lastRatio = -1; tip.style.display = "none"; draw(-1); };

  draw();
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(() => draw(lastRatio)).observe(c.parentElement);
  }
}

// ================= Power-Z ChargerLAB 示波器与微型协议画布 =================
function drawPowerzScope(canvas, samples, pzState) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = rect.width, h = rect.height;
  if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
    canvas.width = w * dpr;
    canvas.height = h * dpr;
  }
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  const padLeft = 45;
  const padRight = 45;
  const padTop = 15;
  const padBottom = 26;
  const plotW = w - padLeft - padRight;
  const plotH = h - padTop - padBottom;

  const ch = (pzState && pzState.channels) ? pzState.channels : { charge: true, power: true, dpdm: true, cc: true, temp: false, energy: false };

  // 1. 动态自适应量程计算
  let maxV = 12.0;
  let maxI = 3.5;
  let maxP = 40.0;
  if (samples && samples.length > 0) {
    for (let k = 0; k < samples.length; k++) {
      if (samples[k].vbus > 12.0) maxV = 24.0;
      if (samples[k].ibus > 3.5) maxI = 6.0;
      if (samples[k].pwr > 40.0) maxP = 100.0;
    }
  }

  // 2. 绘制暗色工业网格与 Y 轴刻度
  ctx.strokeStyle = "rgba(255,255,255,0.06)";
  ctx.lineWidth = 1;
  const gridRows = 5;
  for (let r = 0; r <= gridRows; r++) {
    const y = padTop + (r / gridRows) * plotH;
    ctx.beginPath();
    ctx.moveTo(padLeft, y);
    ctx.lineTo(w - padRight, y);
    ctx.stroke();

    const volt = (maxV - (r / gridRows) * maxV).toFixed(3);
    ctx.fillStyle = "#18a058";
    ctx.font = "10px Consolas, monospace";
    ctx.textAlign = "right";
    ctx.fillText(`${volt}V`, padLeft - 6, y + 3);

    const cur = (maxI - (r / gridRows) * maxI).toFixed(3);
    ctx.fillStyle = "#e05a70";
    ctx.textAlign = "left";
    ctx.fillText(`${cur}A`, w - padRight + 6, y + 3);
  }

  const gridCols = 6;
  for (let c = 0; c <= gridCols; c++) {
    const x = padLeft + (c / gridCols) * plotW;
    ctx.strokeStyle = "rgba(255,255,255,0.05)";
    ctx.beginPath();
    ctx.moveTo(x, padTop);
    ctx.lineTo(x, padTop + plotH);
    ctx.stroke();
  }

  // 图表内原生图例 (In-Chart Legend)
  let legX = padLeft + 12;
  const legY = padTop + 14;
  if (ch.charge !== false) {
    ctx.fillStyle = "#18a058";
    ctx.fillRect(legX, legY - 8, 8, 8);
    ctx.fillStyle = "#cbd5e1";
    ctx.font = "bold 10px Consolas, monospace";
    ctx.textAlign = "left";
    ctx.fillText("VBUS", legX + 12, legY);
    legX += 54;

    ctx.fillStyle = "#e05a70";
    ctx.fillRect(legX, legY - 8, 8, 8);
    ctx.fillStyle = "#cbd5e1";
    ctx.fillText("IBUS", legX + 12, legY);
    legX += 54;
  }
  if (ch.power) {
    ctx.fillStyle = "#2080f0";
    ctx.fillRect(legX, legY - 8, 8, 8);
    ctx.fillStyle = "#cbd5e1";
    ctx.fillText("PWR", legX + 12, legY);
    legX += 48;
  }

  // 水印 POWER-Z (微透)
  ctx.save();
  ctx.font = "900 24px Consolas, monospace";
  ctx.fillStyle = "rgba(255, 255, 255, 0.035)";
  ctx.textAlign = "right";
  ctx.fillText("POWER-Z", w - padRight - 12, h - padBottom - 12);
  ctx.restore();

  // 3. 空闲/未连接状态提示处理
  if (!samples || samples.length < 2) {
    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    if (!pzState || !pzState.isConnected) {
      ctx.font = "600 13px 'Segoe UI', system-ui, sans-serif";
      ctx.fillStyle = "#8c98b2";
      ctx.fillText("🔌 等待连接 ChargerLAB Power-Z 硬件设备...", w / 2, h / 2 - 10);
      ctx.font = "11px 'Segoe UI', system-ui, sans-serif";
      ctx.fillStyle = "#5d6980";
      ctx.fillText("请使用 Type-C 数据线将 KM003C / KM002C 连入电脑 USB 端口", w / 2, h / 2 + 14);
    } else {
      ctx.font = "600 13px 'Segoe UI', system-ui, sans-serif";
      ctx.fillStyle = "#00e676";
      ctx.fillText("⚡ KM003C 物理硬件已就绪，正在同步高精度遥测推流...", w / 2, h / 2);
    }
    ctx.restore();
    ctx.restore();
    return;
  }

  const zoom = (pzState && pzState.zoom) ? pzState.zoom : 1.0;
  const windowCount = Math.min(samples.length, Math.round(300 / zoom));
  const pts = samples.slice(-windowCount);

  // 底部时间轴刻度
  if (pts.length >= 2) {
    const tStart = pts[0].time;
    const tEnd = pts[pts.length - 1].time;
    ctx.fillStyle = "#707d99";
    ctx.font = "10px Consolas, monospace";
    for (let c = 0; c <= gridCols; c++) {
      const x = padLeft + (c / gridCols) * plotW;
      const tAt = tStart + (c / gridCols) * (tEnd - tStart);
      ctx.textAlign = c === 0 ? "left" : c === gridCols ? "right" : "center";
      const s = Math.floor(tAt % 60);
      const m = Math.floor((tAt / 60) % 60);
      ctx.fillText(`${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`, x, h - 8);
    }
  }

  ctx.save();
  ctx.beginPath();
  ctx.rect(padLeft, padTop, plotW, plotH);
  ctx.clip();

  // 4. 各通道曲线渲染 (严格受控于顶部 Pills 开关状态)

  // (1) CHARGE 主通道: VBUS 绿色荧光曲线
  if (ch.charge !== false) {
    ctx.beginPath();
    ctx.strokeStyle = "#00e676";
    ctx.shadowColor = "rgba(0,230,118,0.4)";
    ctx.shadowBlur = 6;
    ctx.lineWidth = 1.8;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const y = padTop + plotH - (pts[i].vbus / maxV) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // IBUS 红色珊瑚曲线
    ctx.beginPath();
    ctx.strokeStyle = "#ff5252";
    ctx.shadowColor = "rgba(255,82,82,0.4)";
    ctx.shadowBlur = 6;
    ctx.lineWidth = 1.8;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const y = padTop + plotH - (pts[i].ibus / maxI) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // (2) POWER 通道: 功率金色流光曲线
  if (ch.power) {
    ctx.beginPath();
    ctx.strokeStyle = "#ffd54f";
    ctx.shadowColor = "rgba(255,213,79,0.45)";
    ctx.shadowBlur = 6;
    ctx.lineWidth = 1.8;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const y = padTop + plotH - (pts[i].pwr / maxP) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // (3) DP/DM 通道: 差分数据线电压曲线 (DP 青蓝 / DM 暖橙)
  if (ch.dpdm) {
    // DP: #00e5ff
    ctx.beginPath();
    ctx.strokeStyle = "#00e5ff";
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.2;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const dpVal = pts[i].dp !== undefined ? pts[i].dp : 0;
      const y = padTop + plotH - (dpVal / 3.6) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // DM: #ff9100
    ctx.beginPath();
    ctx.strokeStyle = "#ff9100";
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.2;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const dmVal = pts[i].dm !== undefined ? pts[i].dm : 0;
      const y = padTop + plotH - (dmVal / 3.6) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // (4) CC1/CC2 通道: 配置通道握手曲线 (CC1 薰衣紫 / CC2 亮紫)
  if (ch.cc) {
    // CC1: #ba68c8
    ctx.beginPath();
    ctx.strokeStyle = "#ba68c8";
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([3, 3]);
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const cc1Val = pts[i].cc1 !== undefined ? pts[i].cc1 : 0;
      const y = padTop + plotH - (cc1Val / 5.0) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // CC2: #7c4dff
    ctx.beginPath();
    ctx.strokeStyle = "#7c4dff";
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([2, 4]);
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const cc2Val = pts[i].cc2 !== undefined ? pts[i].cc2 : 0;
      const y = padTop + plotH - (cc2Val / 5.0) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // (5) TEMP 通道: 温度曲线 (墨绿/青翠)
  if (ch.temp) {
    ctx.beginPath();
    ctx.strokeStyle = "#26a69a";
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.2;
    for (let i = 0; i < pts.length; i++) {
      const x = padLeft + (i / (pts.length - 1)) * plotW;
      const tVal = pts[i].temp !== undefined ? pts[i].temp : 30;
      const y = padTop + plotH - (tVal / 80.0) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // (6) 十字光标动态探针
  if (pzState && pzState.mouseX >= padLeft && pzState.mouseX <= w - padRight) {
    const relX = pzState.mouseX - padLeft;
    const idx = Math.max(0, Math.min(pts.length - 1, Math.round((relX / plotW) * (pts.length - 1))));
    const activePt = pts[idx];
    const snapX = padLeft + (idx / (pts.length - 1)) * plotW;

    ctx.strokeStyle = "rgba(255,255,255,0.25)";
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(snapX, padTop);
    ctx.lineTo(snapX, padTop + plotH);
    ctx.stroke();
    ctx.setLineDash([]);

    if (ch.charge !== false) {
      const snapYv = padTop + plotH - (activePt.vbus / maxV) * plotH;
      const snapYi = padTop + plotH - (activePt.ibus / maxI) * plotH;
      ctx.fillStyle = "#00e676";
      ctx.beginPath(); ctx.arc(snapX, snapYv, 4, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#ff5252";
      ctx.beginPath(); ctx.arc(snapX, snapYi, 4, 0, Math.PI * 2); ctx.fill();
    }
    if (ch.power) {
      const snapYp = padTop + plotH - (activePt.pwr / maxP) * plotH;
      ctx.fillStyle = "#ffd54f";
      ctx.beginPath(); ctx.arc(snapX, snapYp, 4, 0, Math.PI * 2); ctx.fill();
    }
  }

  ctx.restore();
  ctx.restore();
}

function drawPdMiniScope(canvas, pzState) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = rect.width, h = rect.height;
  if (w <= 0 || h <= 0) return;
  if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
    canvas.width = w * dpr; canvas.height = h * dpr;
  }
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  const padLeft = 46;
  const padRight = 50;
  const padTop = 16;
  const padBottom = 22;
  const plotW = Math.max(10, w - padLeft - padRight);
  const plotH = Math.max(10, h - padTop - padBottom);

  // 1. 绘制工业暗色网格与 3 轴刻度
  ctx.strokeStyle = "rgba(255,255,255,0.06)";
  ctx.lineWidth = 1;
  const rows = 5;
  for (let r = 0; r <= rows; r++) {
    const y = padTop + (r / rows) * plotH;
    ctx.beginPath();
    ctx.moveTo(padLeft, y);
    ctx.lineTo(w - padRight, y);
    ctx.stroke();

    // 左轴: VBUS (0.000V ~ 10.000V)
    const vVal = (10.0 - (r / rows) * 10.0).toFixed(3);
    ctx.fillStyle = "#00e5ff";
    ctx.font = "9px Consolas, monospace";
    ctx.textAlign = "right";
    ctx.fillText(`${vVal}V`, padLeft - 5, y + 3);

    // 右轴: IBUS (0.000A ~ 4.000A)
    const iVal = (4.0 - (r / rows) * 4.0).toFixed(3);
    ctx.fillStyle = "#ff5252";
    ctx.textAlign = "left";
    ctx.fillText(`${iVal}A`, w - padRight + 4, y + 3);

    // 最右轴: CC1/CC2 (0.00V ~ 4.00V)
    const ccVal = (4.0 - (r / rows) * 4.0).toFixed(2);
    ctx.fillStyle = "#ba68c8";
    ctx.textAlign = "right";
    ctx.fillText(`${ccVal}V`, w - 2, y + 3);
  }

  const cols = 5;
  for (let c = 0; c <= cols; c++) {
    const x = padLeft + (c / cols) * plotW;
    ctx.beginPath();
    ctx.moveTo(x, padTop);
    ctx.lineTo(x, padTop + plotH);
    ctx.stroke();
  }

  // 底部时间轴刻度
  ctx.fillStyle = "#707d99";
  ctx.font = "9px Consolas, monospace";
  ctx.textAlign = "center";
  const tLabels = ["00:00:00.0", "00:00:20.0", "00:00:40.0", "00:01:00.0", "00:01:20.0", "00:01:40.0"];
  for (let c = 0; c <= cols; c++) {
    const x = padLeft + (c / cols) * plotW;
    ctx.fillText(tLabels[c] || "", x, h - 6);
  }

  if (!pzState || !pzState.pdPackets || pzState.pdPackets.length === 0) {
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "11px 'Segoe UI', system-ui, sans-serif";
    ctx.fillStyle = "#63708a";
    ctx.fillText("🔌 等待连接设备捕获 PD 时序信号...", padLeft + plotW / 2, padTop + plotH / 2);
    ctx.restore();
    return;
  }

  ctx.save();
  ctx.beginPath();
  ctx.rect(padLeft, padTop, plotW, plotH);
  ctx.clip();

  // 2. CC1 BMC 脉冲包 (紫色 #ba68c8)
  const ccZeroY = padTop + plotH - (0.4 / 4.0) * plotH;
  const ccHighY = padTop + plotH - (3.25 / 4.0) * plotH;
  ctx.strokeStyle = "#ba68c8";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(padLeft, ccZeroY);
  const pulseStart = padLeft + plotW * 0.18;
  const pulseEnd = padLeft + plotW * 0.38;
  for (let x = padLeft; x <= w - padRight; x += 2) {
    let y = ccZeroY;
    if (x >= pulseStart && x <= pulseEnd) {
      const freq = (x - pulseStart) * 0.45;
      y = (Math.sin(freq) > 0) ? ccHighY : ccZeroY;
    }
    ctx.lineTo(x, y);
  }
  ctx.stroke();

  // 3. VBUS 阶跃曲线 (青绿 #00e5ff: 5.0V -> 9.0V)
  const v5Y = padTop + plotH - (5.0 / 10.0) * plotH;
  const v9Y = padTop + plotH - (9.0 / 10.0) * plotH;
  const vStepX = padLeft + plotW * 0.35;
  const vRampEnd = padLeft + plotW * 0.48;
  ctx.strokeStyle = "#00e5ff";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(padLeft, v5Y);
  ctx.lineTo(vStepX, v5Y);
  for (let x = vStepX; x <= vRampEnd; x++) {
    const progress = (x - vStepX) / (vRampEnd - vStepX);
    const eased = 0.5 - 0.5 * Math.cos(progress * Math.PI);
    ctx.lineTo(x, v5Y - (v5Y - v9Y) * eased);
  }
  ctx.lineTo(w - padRight, v9Y);
  ctx.stroke();

  // 4. IBUS 阶跃曲线 (珊瑚红 #ff5252: 0.0A -> 2.18A)
  const i0Y = padTop + plotH;
  const i2Y = padTop + plotH - (2.18 / 4.0) * plotH;
  const iStepX = padLeft + plotW * 0.44;
  const iRampEnd = padLeft + plotW * 0.56;
  ctx.strokeStyle = "#ff5252";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(padLeft, i0Y);
  ctx.lineTo(iStepX, i0Y);
  for (let x = iStepX; x <= iRampEnd; x++) {
    const progress = (x - iStepX) / (iRampEnd - iStepX);
    const eased = 0.5 - 0.5 * Math.cos(progress * Math.PI);
    ctx.lineTo(x, i0Y - (i0Y - i2Y) * eased);
  }
  ctx.lineTo(w - padRight, i2Y);
  ctx.stroke();

  // 5. 官方标记 Source Cap 绿色事件戳
  const markerX = padLeft + plotW * 0.72;
  ctx.strokeStyle = "#18a058";
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 2]);
  ctx.beginPath();
  ctx.moveTo(markerX, padTop);
  ctx.lineTo(markerX, padTop + plotH);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.restore();

  // 标记文字 (Source Cap)
  ctx.fillStyle = "#18a058";
  ctx.font = "bold 10px Consolas, monospace";
  ctx.textAlign = "center";
  ctx.fillText("Source Cap", markerX, h - 7);

  ctx.restore();
}

function drawUfcsMiniScope(canvas, pzState) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = rect.width, h = rect.height;
  if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
    canvas.width = w * dpr; canvas.height = h * dpr;
  }
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  ctx.strokeStyle = "rgba(255,255,255,0.06)";
  for (let y = 20; y < h; y += 35) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
  for (let x = 30; x < w; x += 50) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }

  if (!pzState || !pzState.ufcsPackets || pzState.ufcsPackets.length === 0) {
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "12px 'Segoe UI', system-ui, sans-serif";
    ctx.fillStyle = "#63708a";
    ctx.fillText("等待连接设备进行 UFCS 握手捕获...", w / 2, h / 2);
    ctx.restore();
    return;
  }

  // 10mV/10mA 阶梯步进曲线
  ctx.strokeStyle = "#00e676";
  ctx.lineWidth = 2;
  ctx.beginPath();
  const steps = 12;
  for (let s = 0; s <= steps; s++) {
    const x1 = 20 + (s / steps) * (w - 40);
    const x2 = 20 + ((s + 1) / steps) * (w - 40);
    const volt = 5.0 + (s / steps) * 4.2;
    const y = h - ((volt / 11) * (h - 30) + 15);
    if (s === 0) ctx.moveTo(x1, y); else ctx.lineTo(x1, y);
    ctx.lineTo(x2, y);
  }
  ctx.stroke();

  ctx.font = "10px Consolas, monospace";
  ctx.fillStyle = "#00e676"; ctx.fillText("UFCS 10mV/Step 动态调压轨迹 (5.0V → 9.2V)", 14, 20);
  ctx.restore();
}

